import{_ as o,o as a,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Spec — crawler-proxy-readiness","description":"","frontmatter":{},"headers":[],"relativePath":"feature/crawler-proxy-readiness/spec.md","filePath":"feature/crawler-proxy-readiness/spec.md"}'),t={name:"feature/crawler-proxy-readiness/spec.md"};function n(c,e,l,h,d,s){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="spec-—-crawler-proxy-readiness" tabindex="-1">Spec — crawler-proxy-readiness <a class="header-anchor" href="#spec-—-crawler-proxy-readiness" aria-label="Permalink to &quot;Spec — crawler-proxy-readiness&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Crawler không được bỏ một lần crawl chỉ vì proxy KiotProxy vừa cấp chưa kịp nhận kết nối.</p><h2 id="boi-canh" tabindex="-1">Bối cảnh <a class="header-anchor" href="#boi-canh" aria-label="Permalink to &quot;Bối cảnh&quot;">​</a></h2><ul><li>Từ commit <code>ef6fcbd</code> (02/11/2026), <code>prepare_proxy</code> kiểm tra proxy bằng <code>check_proxy</code> trước khi crawl. Kiểm tra thất bại → <code>PROXY_CONNECT_FAILED</code> → cả lần crawl dừng (trước đó crawler vẫn chạy tiếp).</li><li><code>check_proxy</code> thử TCP 3 lần, mỗi lần timeout 4 giây, nghỉ 1 giây: tổng khoảng 14 giây.</li><li>Đo thật ngày 12/11/2026: proxy vừa xin bằng <code>new</code> timeout liên tục, <strong>nhận kết nối ở giây 18,1</strong>, CONNECT tới <code>www.facebook.com:443</code> trả <code>200</code> ở giây 18,3.</li><li>Log production 12/11: proxy cấp lúc <code>09:16:02 UTC</code>, crawl dừng <code>09:16:16 UTC</code> với <code>PROXY_CONNECT_FAILED</code>. Key hợp lệ, <code>allowedIp</code> đúng IP EC2, Security Group cho mọi kết nối đi ra.</li></ul><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>Là admin, khi lịch crawl chạy và crawler phải xin proxy mới, tôi muốn crawler chờ proxy sẵn sàng thay vì kết thúc thất bại, để mỗi ngày đều có dữ liệu trend.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ol><li><code>check_proxy</code> chờ proxy tối đa khoảng 60 giây (12 lần thử, timeout 4 giây, nghỉ 1 giây giữa các lần).</li><li>Proxy nhận kết nối ở lần thử bất kỳ trong khoảng đó → kiểm tra qua, crawl tiếp.</li><li>Proxy không nhận kết nối sau 12 lần → vẫn báo <code>PROXY_CONNECT_FAILED</code> như cũ.</li><li><code>PermissionError</code> (<code>ACCESS_DENIED</code>) vẫn dừng ngay, không thử lại.</li><li>Log vẫn không chứa endpoint, mật khẩu hay nội dung exception; chỉ ghi số lần thử và lý do.</li><li><code>FB_CRAWLER_HTTP_PROXY</code> không bị ghi đè khi kiểm tra thất bại (hành vi hiện có).</li></ol><h2 id="api-contract" tabindex="-1">API Contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API Contract&quot;">​</a></h2><p>Không đổi. <code>check_proxy(value)</code> giữ chữ ký; mã lỗi giữ nguyên.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tình huống</th><th>Kết quả</th></tr></thead><tbody><tr><td>Timeout / từ chối / lỗi mạng</td><td>Thử lại tới lần 12 rồi <code>PROXY_CONNECT_FAILED</code></td></tr><tr><td><code>PermissionError</code></td><td><code>PROXY_CONNECT_FAILED</code> ngay</td></tr><tr><td>Endpoint sai định dạng</td><td><code>PROXY_INVALID_ENDPOINT</code> (không đổi)</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><ul><li>Proxy hỏng hẳn: lần crawl chờ thêm khoảng 45 giây trước khi báo lỗi. Chấp nhận được với lịch crawl hằng ngày.</li><li>Proxy dùng lại bằng <code>current</code> (đã sẵn sàng): thường qua ở lần thử đầu, không chậm thêm.</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p>Code + test pass trong <code>social_crawler/tests/test_proxy_runtime.py</code>; tài liệu 4 file; commit local trên nhánh riêng, chờ người duyệt merge.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Ngưỡng bộ nhớ <code>CRAWLER_RAM_SOFT_PERCENT</code> (container 5 GB).</li><li>Chạy bù lần crawl bị deploy ngắt.</li><li>Cookie Facebook hết hạn.</li><li>Tham số hoá thời gian chờ qua biến môi trường.</li></ul>',19)])])}const u=o(t,[["render",n]]);export{g as __pageData,u as default};
